let x = 'global';
function getX() { return x; } // lexically scoped to global x

function callGetX() {
  let x = 'local';
  return getX(); // still returns 'global' — lexical, not dynamic
}
callGetX(); // 'global'
// In a dynamic scope language, this would return 'local'
